}

.alert.alert-info:before {
  content: '\E055';
}

.alert.alert-warning {
  background: rgba(255, 184, 34, 0.1);
  border-color: rgba(255, 184, 34, 0.1);
}

.alert.alert-warning:before {
  content: '\E617';
}

.alert.alert-danger {
  background: rgba(244, 81, 108, 0.1);
  border-color: rgba(244, 81, 108, 0.1);
}

.alert.alert-danger:before {
  content: '\E01A';
}

.alert .close {
  font-size: 16px;
  opacity: .3;
  position: absolute;
  left: 30px;
  top: 18px;
  padding: 0;
}

.alert .close:hover {
